return [
  {json:{event_id:"evt-001",approved:true,operation:"Create one customer follow-up draft",target:"synthetic-record-A",payload:{message:"hello"}}},
  {json:{event_id:"evt-002",approved:false,operation:"Simulate a charge-like write",target:"synthetic-record-B",payload:{amount:49}}},
  {json:{event_id:"evt-001",approved:true,operation:"duplicate delivery of evt-001",target:"synthetic-record-A",payload:{message:"hello"}}}
];

const seen = new Set();
return items.map(item => {
  const x=item.json;
  if(seen.has(x.event_id)) return {json:{event_id:x.event_id,state:"duplicate_held",outward_action:false,reason:"duplicate event_id",target:x.target}};
  seen.add(x.event_id);
  if(x.approved !== true) return {json:{event_id:x.event_id,state:"awaiting_human_approval",outward_action:false,target:x.target,operation:x.operation}};
  return {json:{event_id:x.event_id,state:"approved_draft_only",outward_action:false,
    target:x.target,operation:x.operation,
    side_effect_draft:{kind:"SIMULATED_WRITE",payload:x.payload,status:"DRAFT_NOT_EXECUTED"}}};
});

const rows=items.map(i=>i.json);
const counts=rows.reduce((a,x)=>(a[x.state]=(a[x.state]||0)+1,a),{});
const checks={
 total_inputs: rows.length,
 all_accounted_for: rows.length===3,
 approved_draft_only: counts.approved_draft_only||0,
 awaiting_human_approval: counts.awaiting_human_approval||0,
 duplicate_held: counts.duplicate_held||0,
 no_outward_actions: rows.every(x=>x.outward_action===false)
};
checks.pass=checks.all_accounted_for && checks.approved_draft_only===1 && checks.awaiting_human_approval===1 && checks.duplicate_held===1 && checks.no_outward_actions;
return [{json:{schema:"little-life-moths.safe-retry-reference.v1",checks,rows,boundary:"Synthetic local demonstration only. No external write nodes are present."}}];
